#[test]
fn test_batch_crawl_basic() {
    common::runtime().block_on(async {
        // Batch crawl of 2 seed URLs with links to discover
        let engine_config: CrawlConfig =
            serde_json::from_str("{\"max_depth\":1,\"respect_robots_txt\":false}").expect("config should parse");
        let engine = create_engine(Some(engine_config)).expect("handle creation should succeed");
        let urls_base = std::env::var("MOCK_SERVER_BATCH_CRAWL_BASIC").unwrap_or_else(|_| {
            let _ = common::mock_server_url();
            std::env::var("MOCK_SERVER_BATCH_CRAWL_BASIC")
                .unwrap_or_else(|_| format!("{}/fixtures/{}", common::mock_server_url(), "batch_crawl_basic"))
        });
        let urls: Vec<String> = [r#"/seed1"#, r#"/seed2"#]
            .into_iter()
            .map(|p: &str| {
                if p.starts_with("http") {
                    p.to_string()
                } else {
                    format!("{}{}", urls_base, p)
                }
            })
            .collect();
        let result = batch_crawl(&engine, urls).await.expect("call failed");
        assert_eq!(result.completed_count, 2, "equals assertion failed");
        assert_eq!(result.failed_count, 0, "equals assertion failed");
        assert_eq!(result.total_count, 2, "equals assertion failed");
    });
}

